import { expect, Journey, test } from './journey.js';

test("The theme control cycles device, light and dark, and is remembered", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.emulate({"colorScheme":"dark"});
    await j.goto("/");
    await expect(j.page.locator("html")).toHaveAttribute("data-scheme", "dark");
    await j.page.getByRole("button", { name: j.re("Change theme") }).click();
    await expect(j.page.locator("html")).toHaveAttribute("data-scheme", "light");
    await j.page.getByRole("button", { name: j.re("Change theme") }).click();
    await expect(j.page.locator("html")).toHaveAttribute("data-scheme", "dark");
    await j.emulate({"colorScheme":"light"});
    await j.reload();
    await expect(j.page.locator("html")).toHaveAttribute("data-scheme", "dark");
    await j.axe("step 11");
  } finally {
    await j.close();
  }
});
